import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

public class Main {
    static final long MOD = 1000000007;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = br.readLine().split(" ");
        long x = Long.parseLong(parts[0]);
        long n = Long.parseLong(parts[1]);

        List<Long> primes = getPrimeFactors(x);

        long result = 1;
        for (long p : primes) {
            long exponent = 0;
            long current = p;
            while (current <= n) {
                exponent += n / current;
                if (current > n / p) {
                    break;
                }
                current *= p;
            }
            result = (result * powMod(p, exponent, MOD)) % MOD;
        }
        System.out.println(result);
    }

    private static long powMod(long base, long exponent, long mod) {
        long result = 1;
        base %= mod;
        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                result = (result * base) % mod;
            }
            exponent >>= 1;
            base = (base * base) % mod;
        }
        return result;
    }

    private static List<Long> getPrimeFactors(long x) {
        List<Long> primes = new ArrayList<>();
        if (x % 2 == 0) {
            primes.add(2L);
            while (x % 2 == 0) {
                x /= 2;
            }
        }
        for (long i = 3; i * i <= x; i += 2) {
            if (x % i == 0) {
                primes.add(i);
                while (x % i == 0) {
                    x /= i;
                }
            }
        }
        if (x > 1) {
            primes.add(x);
        }
        return primes;
    }
}
